  public void testLimit_skipDoesNotExceedLimitWhenUnderlyingSkipReturnsMore() throws Exception {
    // FileInputStream.skip() can skip MORE bytes than requested, even past EOF.
    // LimitedInputStream should not allow reading past the limit even when the
    // underlying stream skips more than requested (see skipSafely in ByteStreams).
    InputStream mockIn = org.mockito.Mockito.mock(InputStream.class);
    // Pretend the underlying stream has 10 bytes available
    org.mockito.Mockito.when(mockIn.available()).thenReturn(10);
    // But when we ask to skip 5, it skips all 10 (violating InputStream.skip contract)
    org.mockito.Mockito.when(mockIn.skip(org.mockito.ArgumentMatchers.anyLong())).thenReturn(10L);
    // The read returns actual data
    org.mockito.Mockito.when(mockIn.read()).thenReturn(1);

    InputStream lin = ByteStreams.limit(mockIn, 5);

    // Skip 5 bytes (which is our entire limit)
    lin.skip(5);

    // After skipping up to the limit, the next read should return -1.
    // The bug: if the underlying skip returned more than 5, left becomes negative
    // (left = 5 - 10 = -5), and the read() check "if (left == 0)" fails, allowing
    // a read past the limit.
    assertEquals(-1, lin.read());
  }

